refentry.refsect1:
&reftitle.description;
arrayarray_column arrayarray intstringnullcolumn_key intstringnullindex_key&null;
Функция array_column возвращает значения одного столбца массива array, который идентифицируется ключом column_key. Необязательный параметр index_key индексирует значения выходного массива значениями столбца index_key входного массива.
Параметр array обрабатывается как список строк, каждая из которых — массив или объект; параметр column_key принимает ключ массива или название объектного свойства, которое встречается в каждой строке. Строки других типов, кроме массива и объекта, или строки, которые не содержат ключа или названия свойства, пропускаются без диагностического сообщения. Ключи массива array не сохраняются.

&reftitle.returnvalues;

 Функция возвращает массив значений, которые представляют один столбец входного массива.
 При передаче в параметре column_key значения &null; возвращаются сами строки.

  &reftitle.examples;



    Пример получения из набора записей столбца с именами


<?php

// Имитация набора записей, которые возвращает база данных
$records = [
    [
        'id' => 2135,
        'first_name' => 'John',
        'last_name' => 'Doe',
    ],
    [
        'id' => 3245,
        'first_name' => 'Sally',
        'last_name' => 'Smith',
    ],
    [
        'id' => 5342,
        'first_name' => 'Jane',
        'last_name' => 'Jones',
    ],
    [
        'id' => 5623,
        'first_name' => 'Peter',
        'last_name' => 'Doe',
    ]
];

$first_names = array_column($records, 'first_name');
print_r($first_names);



    &example.outputs;


Array
(
    [0] => John
    [1] => Sally
    [2] => Jane
    [3] => Peter
)








     Пример получения столбца с фамилиями из набора записей и индексации фамилий значениями столбца "id"



<?php

// Возьмём массив $records из первого примера
$records = [
    [
        'id' => 2135,
        'first_name' => 'John',
        'last_name' => 'Doe',
    ],
    [
        'id' => 3245,
        'first_name' => 'Sally',
        'last_name' => 'Smith',
    ],
    [
        'id' => 5342,
        'first_name' => 'Jane',
        'last_name' => 'Jones',
    ],
    [
        'id' => 5623,
        'first_name' => 'Peter',
        'last_name' => 'Doe',
    ]
];

$last_names = array_column($records, 'last_name', 'id');
print_r($last_names);



    &example.outputs;


Array
(
    [2135] => Doe
    [3245] => Smith
    [5342] => Jones
    [5623] => Doe
)








     Пример получения столбца с именами пользователей из открытого свойства "username"



<?php

class User
{
    public $username;

    public function __construct(string $username)
    {
        $this->username = $username;
    }
}

$users = [
    new User('user 1'),
    new User('user 2'),
    new User('user 3'),
];

print_r(array_column($users, 'username'));



    &example.outputs;


Array
(
    [0] => user 1
    [1] => user 2
    [2] => user 3
)








     Пример получения столбца с именами из закрытого свойства "name"
     путём определения магических методов __isset() и __get()



<?php

class Person
{
    private $name;

    public function __construct(string $name)
    {
        $this->name = $name;
    }

    public function __get($prop)
    {
        return $this->$prop;
    }

    public function __isset($prop) : bool
    {
        return isset($this->$prop);
    }
}

$people = [
    new Person('Fred'),
    new Person('Jane'),
    new Person('John'),
];

print_r(array_column($people, 'name'));



    &example.outputs;


Array
(
    [0] => Fred
    [1] => Jane
    [2] => John
)



   Без метода __isset()
   значение свойства не добавляется в результат.
